declare(strict_types=1); require_once __DIR__.'/server/includes/bootstrap.php'; require_once __DIR__.'/server/includes/view.php'; $user=current_user($pdo); if($user) redirect($user['role']==='admin'?'admin.php':'dashboard.php'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $ip=(string)($_SERVER['REMOTE_ADDR']??'unknown'); if(limited($pdo, 'login:'.$ip,10,900)) $error='Too many sign-in attempts. Please wait 15 minutes before trying again.'; else { $login=post_string('username',190); $pass=(string)($_POST['password']??''); $q=$pdo->prepare('SELECT id,username,password_hash,role,status,must_change_password FROM users WHERE username=? OR email=? LIMIT 1'); $q->execute([$login,$login]); $u=$q->fetch(); if($u && password_verify($pass,$u['password_hash'])) { if($u['status']==='pending') $error='Your account request is waiting for admin approval.'; elseif($u['status']!=='active') $error='This account is not active. Contact the admin team.'; else { session_regenerate_id(true); $_SESSION['uid']=(int)$u['id']; if($u['role']==='admin') $_SESSION['prompt_approvals']=true; $pdo->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([(int)$u['id']]); audit($pdo,(int)$u['id'],'LOGIN','Successful sign-in'); redirect(!empty($u['must_change_password'])?'change-password.php':($u['role']==='admin'?'admin.php':'dashboard.php')); } } else { usleep(180000); $error='Sign-in failed. Check your username/email and password, or recover your password.'; audit($pdo,$u?(int)$u['id']:null,'LOGIN_FAILED','Failed sign-in attempt'); } } }
page_header($config,null,'Member login'); ?><section class="auth-wrap"><div class="auth-card"><div class="eyebrow">Welcome back</div><h1>Member login</h1><p>Each member has their own account. The Owner creates admin accounts separately through Master Admin.</p><?php if($error): ?><div class="flash error"><?=e($error)?></div><?php endif; ?><form method="post"><?=csrf_field()?><label class="field">Username or email<input name="username" maxlength="190" autocomplete="username" required value="<?=e($_POST['username']??'')?>"></label><label class="field">Password<input type="password" name="password" autocomplete="current-password" required></label><button class="btn gold" type="submit">Log in securely</button></form><p class="hint"><a href="forgot.php">Forgot password?</a> · <a href="register.php">Request to join</a></p></div></section><?php page_footer(); ?>